import { spawn } from "node:child_process";
import { dirname, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const pageLimit = "3";
const profileNamePattern = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;

export interface ProofOptions {
  profile: string;
}

export interface CliInvocation {
  argv: readonly string[];
  stdin?: string;
}

export interface CliInvocationResult {
  exitCode: number;
  stdout: string;
  stderr: string;
}

export type CliInvoker = (invocation: CliInvocation) => Promise<CliInvocationResult>;

export interface ProofEntry {
  method: string;
  status: "passed" | "skipped" | "failed";
  detail: string;
}

export interface ProofReport {
  success: boolean;
  entries: readonly ProofEntry[];
}

export interface ProofDependencies {
  environment: NodeJS.ProcessEnv;
  invoke: CliInvoker;
}

export function parseProofOptions(argv: readonly string[]): ProofOptions {
  if (argv.length !== 2 || argv[0] !== "--profile" || !argv[1]) {
    throw new Error("Usage: test:integration -- --profile <name>");
  }
  if (!profileNamePattern.test(argv[1])) {
    throw new Error("The profile name is invalid.");
  }
  return { profile: argv[1] };
}

export function assertLocalProofEnvironment(environment: NodeJS.ProcessEnv): void {
  if (environment.CI || environment.GITHUB_ACTIONS) {
    throw new Error("Profile-backed integration proof is local-only and cannot run in CI/CD.");
  }
}

function objectValue(value: unknown, description: string): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`${description} was not an object.`);
  }
  return value as Record<string, unknown>;
}

function arrayValue(value: unknown, description: string): unknown[] {
  if (!Array.isArray(value)) {
    throw new Error(`${description} was not an array.`);
  }
  return value;
}

function itemId(value: unknown): string | undefined {
  const item = objectValue(value, "List item");
  const id = item.id;
  return typeof id === "string" || typeof id === "number" ? String(id) : undefined;
}

function pageSummary(value: unknown, requireId = false): string {
  const items = arrayValue(value, "Collection response");
  if (items.length > Number(pageLimit)) {
    throw new Error("Collection response exceeded its requested limit.");
  }
  if (requireId && items.length > 0 && itemId(items[0]) === undefined) {
    throw new Error("Collection item ID is missing.");
  }
  return `${items.length} item(s)`;
}

export async function runProfileProof(
  options: ProofOptions,
  dependencies: ProofDependencies,
): Promise<ProofReport> {
  assertLocalProofEnvironment(dependencies.environment);
  const entries: ProofEntry[] = [];

  const executeJson = async (
    method: string,
    argv: readonly string[],
    inspect: (value: unknown) => string,
  ): Promise<unknown | undefined> => {
    let invocation: CliInvocationResult;
    try {
      invocation = await dependencies.invoke({
        argv: [...argv, "--profile", options.profile, "--json"],
      });
    } catch {
      entries.push({ method, status: "failed", detail: "CLI process could not start" });
      return undefined;
    }
    if (invocation.exitCode !== 0) {
      entries.push({
        method,
        status: "failed",
        detail: `CLI exited with code ${invocation.exitCode}`,
      });
      return undefined;
    }
    try {
      const value: unknown = JSON.parse(invocation.stdout);
      entries.push({ method, status: "passed", detail: inspect(value) });
      return value;
    } catch {
      entries.push({ method, status: "failed", detail: "invalid JSON or response shape" });
      return undefined;
    }
  };

  const skip = (method: string, detail: string): void => {
    entries.push({ method, status: "skipped", detail });
  };

  await executeJson("permissions list", ["permissions", "list"], (value) => {
    const permissions = arrayValue(value, "Permissions response").map((item) =>
      objectValue(item, "Permission"),
    );
    const readOnly = permissions.find((item) => item.name === "ReadOnly");
    if (readOnly?.enabled !== true) {
      throw new Error("ReadOnly permission is disabled.");
    }
    return "ReadOnly enabled";
  });
  await executeJson("auth status", ["auth", "status"], (value) => {
    if (objectValue(value, "Authentication response").authenticated !== true) {
      throw new Error("Profile is not authenticated.");
    }
    return "authenticated";
  });
  await executeJson("server status", ["server", "status"], (value) => {
    if (typeof objectValue(value, "Server response").version !== "string") {
      throw new Error("Server version is missing.");
    }
    return "response parsed";
  });

  const projects = await executeJson(
    "projects list",
    ["projects", "list", "--limit", pageLimit],
    (value) => pageSummary(value, true),
  );
  const projectItems = projects === undefined ? undefined : arrayValue(projects, "Projects response");
  const projectId = projectItems?.[0] === undefined ? undefined : itemId(projectItems[0]);
  if (projectId) {
    await executeJson("projects show", ["projects", "show", projectId], (value) => {
      objectValue(value, "Project response");
      return "response parsed";
    });
  } else {
    skip("projects show", projectItems === undefined ? "source list failed" : "source list empty");
  }

  const jobs = await executeJson(
    "jobs list",
    ["jobs", "list", "--limit", pageLimit],
    (value) => pageSummary(value, true),
  );
  const jobItems = jobs === undefined ? undefined : arrayValue(jobs, "Jobs response");
  const jobId = jobItems?.[0] === undefined ? undefined : itemId(jobItems[0]);
  if (jobId) {
    await executeJson("jobs show", ["jobs", "show", jobId], (value) => {
      objectValue(value, "Job response");
      return "response parsed";
    });
    await executeJson("jobs status", ["jobs", "status", jobId], (value) => {
      objectValue(value, "Job status response");
      return "response parsed";
    });
  } else {
    const reason = jobItems === undefined ? "source list failed" : "source list empty";
    skip("jobs show", reason);
    skip("jobs status", reason);
  }

  const builds = await executeJson(
    "builds list",
    ["builds", "list", "--limit", pageLimit],
    (value) => pageSummary(value, true),
  );
  const buildItems = builds === undefined ? undefined : arrayValue(builds, "Builds response");
  const buildId = buildItems?.[0] === undefined ? undefined : itemId(buildItems[0]);
  if (buildId) {
    await executeJson("builds show", ["builds", "show", buildId], (value) => {
      objectValue(value, "Build response");
      return "response parsed";
    });
    for (const diagnostic of ["tests", "problems", "changes"] as const) {
      await executeJson(
        `builds ${diagnostic}`,
        ["builds", diagnostic, buildId, "--limit", pageLimit],
        (value) => pageSummary(value),
      );
    }
  } else {
    const reason = buildItems === undefined ? "source list failed" : "source list empty";
    for (const method of ["builds show", "builds tests", "builds problems", "builds changes"]) {
      skip(method, reason);
    }
  }

  await executeJson(
    "queue list",
    ["queue", "list", "--limit", pageLimit],
    (value) => pageSummary(value),
  );

  const agents = await executeJson(
    "agents list",
    ["agents", "list", "--limit", pageLimit],
    (value) => pageSummary(value, true),
  );
  const agentItems = agents === undefined ? undefined : arrayValue(agents, "Agents response");
  const agentId = agentItems?.[0] === undefined ? undefined : itemId(agentItems[0]);
  if (agentId) {
    await executeJson("agents show", ["agents", "show", agentId], (value) => {
      objectValue(value, "Agent response");
      return "response parsed";
    });
  } else {
    skip("agents show", agentItems === undefined ? "source list failed" : "source list empty");
  }

  const rpcInput = [
    {
      jsonrpc: "2.0",
      id: 1,
      method: "cli.execute",
      params: { argv: ["server", "status", "--profile", options.profile] },
    },
    {
      jsonrpc: "2.0",
      id: 2,
      method: "cli.execute",
      params: { argv: ["queue", "list", "--limit", "1", "--profile", options.profile] },
    },
  ]
    .map((frame) => JSON.stringify(frame))
    .join("\n");
  try {
    const invocation = await dependencies.invoke({
      argv: ["--json-rpc"],
      stdin: `${rpcInput}\n`,
    });
    if (invocation.exitCode !== 0) {
      entries.push({
        method: "JSON-RPC session",
        status: "failed",
        detail: `CLI exited with code ${invocation.exitCode}`,
      });
    } else {
      const frames = invocation.stdout
        .trim()
        .split("\n")
        .filter(Boolean)
        .map((line) => objectValue(JSON.parse(line) as unknown, "JSON-RPC frame"));
      if (
        frames.length !== 2 ||
        frames[0]?.id !== 1 ||
        frames[1]?.id !== 2 ||
        frames.some((frame) => frame.error !== undefined)
      ) {
        throw new Error("Unexpected JSON-RPC response.");
      }
      if (
        typeof objectValue(frames[0]!.result, "JSON-RPC server response").version !== "string" ||
        arrayValue(frames[1]!.result, "JSON-RPC queue response").length > 1
      ) {
        throw new Error("Unexpected JSON-RPC result shape.");
      }
      entries.push({ method: "JSON-RPC session", status: "passed", detail: "2 responses" });
    }
  } catch {
    entries.push({ method: "JSON-RPC session", status: "failed", detail: "invalid response" });
  }

  return {
    success: entries.every((entry) => entry.status !== "failed"),
    entries,
  };
}

export function formatProofReport(report: ProofReport): string {
  const labels = { passed: "PASS", skipped: "SKIP", failed: "FAIL" } as const;
  const lines = report.entries.map(
    (entry) => `${labels[entry.status]} ${entry.method} — ${entry.detail}`,
  );
  const passed = report.entries.filter((entry) => entry.status === "passed").length;
  const skipped = report.entries.filter((entry) => entry.status === "skipped").length;
  const failed = report.entries.filter((entry) => entry.status === "failed").length;
  lines.push(`Summary: ${passed} passed, ${skipped} skipped, ${failed} failed`);
  return `${lines.join("\n")}\n`;
}

export function createProcessInvoker(): CliInvoker {
  const cliPath = resolve(dirname(fileURLToPath(import.meta.url)), "../src/bin.js");
  return ({ argv, stdin }) =>
    new Promise<CliInvocationResult>((resolveInvocation, reject) => {
      const child = spawn(process.execPath, [cliPath, ...argv], {
        stdio: ["pipe", "pipe", "pipe"],
        windowsHide: true,
        timeout: 30_000,
      });
      let stdout = "";
      let stderr = "";
      child.stdout.setEncoding("utf8");
      child.stderr.setEncoding("utf8");
      child.stdout.on("data", (chunk: string) => {
        stdout += chunk;
      });
      child.stderr.on("data", (chunk: string) => {
        stderr += chunk;
      });
      child.once("error", reject);
      child.stdin.once("error", reject);
      child.once("close", (exitCode) => {
        resolveInvocation({ exitCode: exitCode ?? 1, stdout, stderr });
      });
      child.stdin.end(stdin);
    });
}

async function main(): Promise<void> {
  try {
    const options = parseProofOptions(process.argv.slice(2));
    const report = await runProfileProof(options, {
      environment: process.env,
      invoke: createProcessInvoker(),
    });
    process.stdout.write(formatProofReport(report));
    if (!report.success) {
      process.exitCode = 1;
    }
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : "Integration proof failed."}\n`);
    process.exitCode = 2;
  }
}

const entryUrl = process.argv[1] ? pathToFileURL(resolve(process.argv[1])).href : undefined;
if (entryUrl === import.meta.url) {
  await main();
}

#!/usr/bin/env node
import { createTeamCityCli } from "./cli.js";

process.exitCode = await createTeamCityCli().run();

import {
  command,
  createCli,
  Permission,
  tokenAuth,
  type CliApplication,
  type CliRuntime,
  type CommandContext,
  type OptionDefinition,
  type Profile,
} from "@eyeauras/cli-factory";
import { TeamCityClient } from "./client.js";
import type {
  TeamCityBuildState,
  TeamCityBuildStatus,
  TeamCityTestStatus,
  TeamCityTriState,
} from "./models.js";

const pageOptions: readonly OptionDefinition[] = [
  {
    flags: "--limit <count>",
    description: "Maximum results to return (1-100)",
    defaultValue: 100,
    parse: pageLimit,
  },
  {
    flags: "--start <offset>",
    description: "Zero-based result offset",
    defaultValue: 0,
    parse: nonNegativeInteger,
  },
];

function profileUrl(profile: Profile): string {
  const value = profile.values.url;
  if (typeof value !== "string") {
    throw new Error(`Profile '${profile.name}' has no TeamCity URL.`);
  }
  return value;
}

async function client(context: CommandContext): Promise<TeamCityClient> {
  const guest = context.profile.values.guest === true;
  return new TeamCityClient({
    baseUrl: profileUrl(context.profile),
    ...(guest ? { guest: true } : { token: await context.secrets.require("token") }),
    fetch: context.fetch,
    signal: context.signal,
  });
}

function integer(value: string, description: string): number {
  if (!/^-?\d+$/.test(value)) {
    throw new Error(`${description} must be an integer.`);
  }
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed)) {
    throw new Error(`${description} must be a safe integer.`);
  }
  return parsed;
}

function positiveInteger(value: string): number {
  const parsed = integer(value, "Expected value");
  if (parsed <= 0) {
    throw new Error("Expected a positive integer.");
  }
  return parsed;
}

function nonNegativeInteger(value: string): number {
  const parsed = integer(value, "Expected value");
  if (parsed < 0) {
    throw new Error("Expected a non-negative integer.");
  }
  return parsed;
}

function pageLimit(value: string): number {
  const parsed = integer(value, "TeamCity page limit");
  if (parsed < 1 || parsed > 100) {
    throw new Error("TeamCity page limit must be between 1 and 100.");
  }
  return parsed;
}

function oneOf<const T extends string>(
  description: string,
  values: readonly T[],
): (value: string) => T {
  return (value) => {
    if (!values.includes(value as T)) {
      throw new Error(`${description} must be one of: ${values.join(", ")}.`);
    }
    return value as T;
  };
}

function stringOption(options: Record<string, unknown>, name: string): string | undefined {
  const value = options[name];
  return typeof value === "string" ? value : undefined;
}

function numberOption(options: Record<string, unknown>, name: string): number | undefined {
  const value = options[name];
  return typeof value === "number" ? value : undefined;
}

function pageValues(options: Record<string, unknown>): { limit?: number; start?: number } {
  const limit = numberOption(options, "limit");
  const start = numberOption(options, "start");
  return {
    ...(limit === undefined ? {} : { limit }),
    ...(start === undefined ? {} : { start }),
  };
}

const buildState = oneOf<TeamCityBuildState>("Build state", [
  "queued",
  "running",
  "finished",
  "any",
]);
const buildStatus = oneOf<TeamCityBuildStatus>("Build status", [
  "SUCCESS",
  "FAILURE",
  "UNKNOWN",
]);
const testStatus = oneOf<TeamCityTestStatus>("Test status", [
  "unknown",
  "normal",
  "warning",
  "failure",
  "error",
  "success",
]);
const triState = oneOf<TeamCityTriState>("Agent filter", ["true", "false", "any"]);

export function createTeamCityCli(runtime?: CliRuntime): CliApplication {
  return createCli({
    name: "teamcity-cli",
    description: "AI-friendly access to TeamCity",
    version: "0.1.0",
    applicationId: "teamcity-cli",
    permissions: {},
    profile: {
      fields: [
        {
          name: "url",
          flags: "--url <url>",
          description: "TeamCity server URL",
          required: true,
        },
        {
          name: "guest",
          flags: "--guest",
          description: "Use TeamCity guest access without a token",
        },
        {
          name: "guest",
          flags: "--no-guest",
          description: "Use token authentication",
        },
      ],
      validate(values) {
        const url = values.url;
        if (url !== undefined && (typeof url !== "string" || !/^https?:\/\//.test(url))) {
          throw new Error("A TeamCity profile URL must start with http:// or https://.");
        }
        if (values.guest !== undefined && typeof values.guest !== "boolean") {
          throw new Error("TeamCity guest mode must be a boolean.");
        }
      },
    },
    auth: tokenAuth({
      env: "TEAMCITY_TOKEN",
      required: (profile) => profile.values.guest !== true,
      async validate({ profile, token, fetch, signal }) {
        return new TeamCityClient({ baseUrl: profileUrl(profile), token, fetch, signal }).currentUser();
      },
    }),
    commands: [
      command("server", "Inspect the TeamCity server", [
        command(
          "status",
          "Show TeamCity version, role, and clock information",
          async (_input, context) => (await client(context)).getServerStatus(),
          { permission: Permission.ReadOnly },
        ),
      ]),
      command("projects", "Work with TeamCity projects", [
        command(
          "list",
          "List projects",
          async ({ options }, context) => {
            const parent = stringOption(options, "parent");
            return (await client(context)).listProjects({
              ...(parent === undefined ? {} : { parent }),
              ...(options.includeArchived === true ? { includeArchived: true } : {}),
              ...pageValues(options),
            });
          },
          {
            permission: Permission.ReadOnly,
            options: [
              { flags: "--parent <id>", description: "Limit projects to one parent project" },
              { flags: "--include-archived", description: "Include archived projects" },
              ...pageOptions,
            ],
          },
        ),
        command(
          "show <id>",
          "Show one project",
          async ({ args }, context) => (await client(context)).getProject(String(args.id)),
          { permission: Permission.ReadOnly },
        ),
      ]),
      command("jobs", "Work with TeamCity build configurations", [
        command(
          "list",
          "List jobs",
          async ({ options }, context) => {
            const project = stringOption(options, "project");
            return (await client(context)).listJobs({
              ...(project === undefined ? {} : { project }),
              ...pageValues(options),
            });
          },
          {
            permission: Permission.ReadOnly,
            options: [
              { flags: "--project <id>", description: "Limit jobs to a TeamCity project" },
              ...pageOptions,
            ],
          },
        ),
        command(
          "show <id>",
          "Show one job",
          async ({ args }, context) => (await client(context)).getJob(String(args.id)),
          { permission: Permission.ReadOnly },
        ),
        command(
          "status <id>",
          "Show the latest operational build status for a job",
          async ({ args }, context) => (await client(context)).getJobStatus(String(args.id)),
          { permission: Permission.ReadOnly },
        ),
        command(
          "run <id>",
          "Queue a new build for a job",
          async ({ args, options }, context) => {
            const branch = stringOption(options, "branch");
            const comment = stringOption(options, "comment");
            return (await client(context)).runJob(String(args.id), {
              ...(branch === undefined ? {} : { branch }),
              ...(comment === undefined ? {} : { comment }),
            });
          },
          {
            permission: Permission.Update,
            options: [
              { flags: "--branch <name>", description: "Build a specific branch" },
              { flags: "--comment <text>", description: "Attach a queue comment" },
            ],
          },
        ),
      ]),
      command("builds", "Inspect and control TeamCity builds", [
        command(
          "list",
          "List operational builds across all branches",
          async ({ options }, context) => {
            const job = stringOption(options, "job");
            const project = stringOption(options, "project");
            const state = stringOption(options, "state") as TeamCityBuildState | undefined;
            const status = stringOption(options, "status") as TeamCityBuildStatus | undefined;
            return (await client(context)).listBuilds({
              ...(job === undefined ? {} : { job }),
              ...(project === undefined ? {} : { project }),
              ...(state === undefined ? {} : { state }),
              ...(status === undefined ? {} : { status }),
              ...pageValues(options),
            });
          },
          {
            permission: Permission.ReadOnly,
            options: [
              { flags: "--job <id>", description: "Limit builds to one job" },
              { flags: "--project <id>", description: "Limit builds to one affected project" },
              {
                flags: "--state <state>",
                description: "queued, running, finished, or any",
                parse: buildState,
              },
              {
                flags: "--status <status>",
                description: "SUCCESS, FAILURE, or UNKNOWN",
                parse: buildStatus,
              },
              ...pageOptions,
            ],
          },
        ),
        command(
          "show <id>",
          "Show one build",
          async ({ args }, context) =>
            (await client(context)).getBuild(positiveInteger(String(args.id))),
          { permission: Permission.ReadOnly },
        ),
        command(
          "tests <id>",
          "List test occurrences for a build",
          async ({ args, options }, context) => {
            const status = stringOption(options, "status") as TeamCityTestStatus | undefined;
            return (await client(context)).listBuildTests(positiveInteger(String(args.id)), {
              ...(status === undefined ? {} : { status }),
              ...pageValues(options),
            });
          },
          {
            permission: Permission.ReadOnly,
            options: [
              {
                flags: "--status <status>",
                description: "TeamCity test status",
                parse: testStatus,
              },
              ...pageOptions,
            ],
          },
        ),
        command(
          "problems <id>",
          "List problem occurrences for a build",
          async ({ args, options }, context) =>
            (await client(context)).listBuildProblems(
              positiveInteger(String(args.id)),
              pageValues(options),
            ),
          { permission: Permission.ReadOnly, options: pageOptions },
        ),
        command(
          "changes <id>",
          "List source changes associated with a build",
          async ({ args, options }, context) =>
            (await client(context)).listBuildChanges(
              positiveInteger(String(args.id)),
              pageValues(options),
            ),
          { permission: Permission.ReadOnly, options: pageOptions },
        ),
        command(
          "cancel <id>",
          "Cancel a running build",
          async ({ args, options }, context) => {
            const comment = stringOption(options, "comment");
            return (await client(context)).cancelBuild(positiveInteger(String(args.id)), {
              ...(comment === undefined ? {} : { comment }),
            });
          },
          {
            permission: Permission.Update,
            options: [{ flags: "--comment <text>", description: "Explain the cancellation" }],
          },
        ),
      ]),
      command("queue", "Inspect and control the TeamCity build queue", [
        command(
          "list",
          "List queued builds",
          async ({ options }, context) => {
            const job = stringOption(options, "job");
            const project = stringOption(options, "project");
            return (await client(context)).listQueue({
              ...(job === undefined ? {} : { job }),
              ...(project === undefined ? {} : { project }),
              ...pageValues(options),
            });
          },
          {
            permission: Permission.ReadOnly,
            options: [
              { flags: "--job <id>", description: "Limit queued builds to one job" },
              { flags: "--project <id>", description: "Limit queued builds to one project" },
              ...pageOptions,
            ],
          },
        ),
        command(
          "cancel <id>",
          "Cancel a queued build",
          async ({ args, options }, context) => {
            const comment = stringOption(options, "comment");
            return (await client(context)).cancelQueuedBuild(positiveInteger(String(args.id)), {
              ...(comment === undefined ? {} : { comment }),
            });
          },
          {
            permission: Permission.Update,
            options: [{ flags: "--comment <text>", description: "Explain the cancellation" }],
          },
        ),
      ]),
      command("agents", "Inspect TeamCity build agents", [
        command(
          "list",
          "List build agents",
          async ({ options }, context) => {
            const connected = stringOption(options, "connected") as TeamCityTriState | undefined;
            const enabled = stringOption(options, "enabled") as TeamCityTriState | undefined;
            const authorized = stringOption(options, "authorized") as TeamCityTriState | undefined;
            return (await client(context)).listAgents({
              ...(connected === undefined ? {} : { connected }),
              ...(enabled === undefined ? {} : { enabled }),
              ...(authorized === undefined ? {} : { authorized }),
              ...pageValues(options),
            });
          },
          {
            permission: Permission.ReadOnly,
            options: [
              {
                flags: "--connected <value>",
                description: "true, false, or any",
                parse: triState,
              },
              {
                flags: "--enabled <value>",
                description: "true, false, or any",
                parse: triState,
              },
              {
                flags: "--authorized <value>",
                description: "true, false, or any",
                parse: triState,
              },
              ...pageOptions,
            ],
          },
        ),
        command(
          "show <id>",
          "Show one build agent",
          async ({ args }, context) =>
            (await client(context)).getAgent(positiveInteger(String(args.id))),
          { permission: Permission.ReadOnly },
        ),
      ]),
    ],
    ...(runtime === undefined ? {} : { runtime }),
  });
}

import {
  idPath,
  joinLocator,
  nestedId,
  pageDimensions,
  positiveId,
  requiredText,
