  assert.equal(await cli.run([]), 0);
  for (const branch of ["server", "projects", "jobs", "builds", "queue", "agents"]) {
    assert.match(testRuntime.stdout(), new RegExp(`\\b${branch}\\b`));
  }

  for (const [branch, leaf] of [
    ["server", "status"],
    ["projects", "list"],
    ["jobs", "run"],
    ["builds", "tests"],
    ["queue", "cancel"],
    ["agents", "show"],
  ] as const) {
