export async function uploadIssueAttachment(
  connection: Connection,
  issueID: string,
  filePath: string,
): Promise<YouTrackObject[] | null> {
  const path = `${issuePath(issueID)}/attachments`;
  requiredText(filePath, "file path");
  let file: Blob;
  try {
    if (!(await fs.promises.stat(filePath)).isFile()) {
      throw new Error();
    }
    file = await fs.openAsBlob(filePath);
  } catch {
    throw new Error("YouTrack upload requires a readable regular file.");
  }
  const form = new FormData();
  form.append("upload1", file, basename(filePath));
  return uploadObjectCollection(connection, path, form, attachmentFields);
}

