  assert.match(f.stdout(), /fixture.bin/);
  await f.cli.execute(["permissions", "grant", "Update", "--profile", "dev"]);
  assert.deepEqual(await f.cli.execute(["issues", "attachments", "upload", "fixture-issue", "--file", f.file, "--profile", "dev"]), [metadata]);
