} from "./types.js";

import { createInterface } from "node:readline";
import type { Readable, Writable } from "node:stream";

interface JsonRpcRequest {
  jsonrpc: "2.0";
  id?: string | number | null;
  method: string;
  params?: unknown;
}

interface ExecuteParams {
  argv: string[];
}

function isRequest(value: unknown): value is JsonRpcRequest {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const candidate = value as Partial<JsonRpcRequest>;
  return candidate.jsonrpc === "2.0" && typeof candidate.method === "string";
}

function executeParams(value: unknown): ExecuteParams | undefined {
  if (typeof value !== "object" || value === null) {
    return undefined;
  }
  const argv = (value as Partial<ExecuteParams>).argv;
  return Array.isArray(argv) && argv.every((entry) => typeof entry === "string")
    ? { argv }
    : undefined;
}

function response(output: Writable, value: unknown): void {
  output.write(`${JSON.stringify(value)}\n`);
}

function errorResponse(
  output: Writable,
  id: JsonRpcRequest["id"],
  code: number,
  message: string,
): void {
  response(output, {
    jsonrpc: "2.0",
    id: id ?? null,
    error: { code, message },
  });
}

export async function runJsonRpc(options: {
  input: Readable;
  output: Writable;
  execute: (argv: readonly string[]) => Promise<unknown>;
}): Promise<void> {
  const lines = createInterface({ input: options.input, crlfDelay: Infinity });
  for await (const line of lines) {
    if (!line.trim()) {
      continue;
    }

    let request: unknown;
    try {
      request = JSON.parse(line);
    } catch {
      errorResponse(options.output, null, -32700, "Parse error");
      continue;
    }

    if (!isRequest(request)) {
      errorResponse(options.output, null, -32600, "Invalid Request");
      continue;
    }

    const expectsResponse = request.id !== undefined;
    if (request.method !== "cli.execute") {
      if (expectsResponse) {
        errorResponse(options.output, request.id, -32601, "Method not found");
      }
      continue;
    }

    const params = executeParams(request.params);
    if (!params) {
      if (expectsResponse) {
        errorResponse(options.output, request.id, -32602, "Expected params.argv to be a string array");
      }
      continue;
    }

    try {
      const result = await options.execute(params.argv);
      if (expectsResponse) {
        response(options.output, { jsonrpc: "2.0", id: request.id ?? null, result: result ?? null });
      }
    } catch (error) {
      if (expectsResponse) {
        errorResponse(
          options.output,
          request.id,
          -32000,
          error instanceof Error ? error.message : String(error),
        );
      }
    }
  }
}

import { inspect } from "node:util";
import type { Writable } from "node:stream";

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function displayCell(value: unknown): string {
  if (value === null || value === undefined) {
    return "";
  }
  if (typeof value === "object") {
    return JSON.stringify(value);
  }
  return String(value);
}

function table(values: readonly Record<string, unknown>[]): string {
  const columns = [...new Set(values.flatMap((value) => Object.keys(value)))];
  if (columns.length === 0) {
    return "";
  }

  const rows = values.map((value) => columns.map((column) => displayCell(value[column])));
  const widths = columns.map((column, index) =>
    Math.max(column.length, ...rows.map((row) => row[index]?.length ?? 0)),
  );
  const formatRow = (row: readonly string[]): string =>
    row.map((cell, index) => cell.padEnd(widths[index] ?? 0)).join("  ").trimEnd();

  return [
    formatRow(columns),
    formatRow(widths.map((width) => "-".repeat(width))),
    ...rows.map(formatRow),
  ].join("\n");
}

export function formatHuman(value: unknown): string {
  if (value === undefined || value === null) {
    return "";
  }
  if (typeof value === "string") {
    return value;
  }
  if (Array.isArray(value) && value.every(isRecord)) {
    if (value.length === 0) {
      return "No results.";
    }
    return table(value);
  }
  if (isRecord(value)) {
    return Object.entries(value)
      .map(([key, entry]) => `${key}: ${displayCell(entry)}`)
      .join("\n");
  }
  return inspect(value, { colors: false, depth: 6, compact: false });
}

export function writeResult(output: Writable, value: unknown, json: boolean): void {
  const rendered = json ? JSON.stringify(value ?? null) : formatHuman(value);
  if (rendered.length > 0) {
    output.write(`${rendered}\n`);
  }
}

import type {
  CommandDefinition,
  PermissionCategory,
  PermissionGateDefinition,
} from "./types.js";

export const Permission = Object.freeze({
  ReadOnly: "ReadOnly",
  Update: "Update",
} as const);

const builtInCategories: readonly PermissionCategory[] = [
  {
    name: Permission.ReadOnly,
    description: "Read remote state without changing it",
    enabledByDefault: true,
  },
  {
    name: Permission.Update,
    description: "Perform operations that may change remote state",
    enabledByDefault: false,
  },
];

const categoryNamePattern = /^[A-Za-z][A-Za-z0-9._-]{0,63}$/;

export function resolvePermissionCategories(
  definition: PermissionGateDefinition,
): readonly PermissionCategory[] {
  const categories = [...builtInCategories, ...(definition.categories ?? [])];
  const names = new Set<string>();
  for (const category of categories) {
    if (!categoryNamePattern.test(category.name)) {
      throw new Error(
        `Permission category '${category.name}' must start with a letter and contain at most 64 letters, numbers, dots, dashes, or underscores.`,
      );
    }
    if (names.has(category.name)) {
      throw new Error(`Permission category '${category.name}' is declared more than once.`);
    }
    names.add(category.name);
  }
  return categories;
}

export function validateCommandPermissions(
  commands: readonly CommandDefinition[],
  categories: readonly PermissionCategory[],
): void {
  const known = new Set(categories.map((category) => category.name));
  const visit = (command: CommandDefinition, parentPath: string): void => {
    const commandName = command.name.trim().split(/\s+/, 1)[0] ?? command.name;
    const path = parentPath ? `${parentPath} ${commandName}` : commandName;
    if (command.run && !command.permission) {
      throw new Error(
        `Command '${path}' must declare a permission because the permission gate is enabled.`,
      );
    }
    if (command.permission && !known.has(command.permission)) {
      throw new Error(
        `Command '${path}' requires unknown permission '${command.permission}'.`,
      );
    }
    for (const child of command.children ?? []) {
      visit(child, path);
    }
  };
  for (const command of commands) {
    visit(command, "");
  }
}

export function validatePermissionsDisabled(commands: readonly CommandDefinition[]): void {
  const visit = (command: CommandDefinition): void => {
    if (command.permission) {
      throw new Error(
        `Command '${command.name}' declares permission '${command.permission}', but the CLI permission gate is not enabled.`,
      );
    }
    for (const child of command.children ?? []) {
      visit(child);
    }
  };
  for (const command of commands) {
    visit(command);
  }
}

import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { AppArguments, type IAppArguments } from "./app-arguments.js";
import type {
  Profile,
  ProfileStoreContract,
  ProfileValues,
} from "./types.js";

interface ProfileDocument {
  version: 1;
  active: string;
  profiles: Record<string, ProfileValues>;
  permissions?: Record<string, string[]>;
}

export interface ProfileStoreOptions {
  applicationId: string;
  defaultName?: string;
  defaults?: ProfileValues;
  rootDirectory?: string;
  appArguments?: IAppArguments;
  validate?: (values: ProfileValues) => void | Promise<void>;
}

const profileNamePattern = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;

export function assertProfileName(name: string): void {
  if (!profileNamePattern.test(name)) {
    throw new Error(
      "Profile names must start with a letter or number and contain at most 64 letters, numbers, dots, dashes, or underscores.",
    );
  }
  if (name.toLowerCase() === "profiles.json") {
    throw new Error("Profile name 'profiles.json' is reserved for the application profile index.");
  }
}

export class ProfileStore implements ProfileStoreContract {
  readonly #filePath: string;
  readonly #defaultName: string;
  readonly #defaults: ProfileValues;
  readonly #validate: ((values: ProfileValues) => void | Promise<void>) | undefined;

  public constructor(options: ProfileStoreOptions) {
    this.#defaultName = options.defaultName ?? "default";
    assertProfileName(this.#defaultName);
    this.#defaults = structuredClone(options.defaults ?? {});
    this.#validate = options.validate;
    const appArguments =
      options.appArguments ??
      new AppArguments({
        AppName: options.applicationId,
        Profile: this.#defaultName,
        ...(options.rootDirectory === undefined
          ? {}
          : {
              Environment: {
                ...AppArguments.CurrentEnvironment(),
                EnvironmentAppData: options.rootDirectory,
                EnvironmentLocalAppData: options.rootDirectory,
              },
            }),
      });
    if (appArguments.AppName !== options.applicationId) {
      throw new Error(
        `ProfileStore applicationId '${options.applicationId}' does not match AppArguments.AppName '${appArguments.AppName}'.`,
      );
    }
    this.#filePath = join(appArguments.RoamingAppDataDirectory, "profiles.json");
  }

  public async get(name?: string): Promise<Profile> {
    const document = await this.#load();
    const selectedName = name ?? document.active;
    const values = document.profiles[selectedName];
    if (!values) {
      throw new Error(`Profile '${selectedName}' does not exist.`);
    }

    return { name: selectedName, values: structuredClone(values) };
  }

  public async list(): Promise<{ active: string; profiles: Profile[] }> {
    const document = await this.#load();
    return {
      active: document.active,
      profiles: Object.entries(document.profiles).map(([name, values]) => ({
        name,
        values: structuredClone(values),
      })),
    };
  }

  public async create(name: string, values: ProfileValues = {}): Promise<Profile> {
    assertProfileName(name);
    const document = await this.#load();
    if (document.profiles[name]) {
      throw new Error(`Profile '${name}' already exists.`);
    }
    const nextValues = { ...this.#defaults, ...values };
    await this.#validate?.(nextValues);
    document.profiles[name] = nextValues;
    await this.#save(document);
    return { name, values: structuredClone(nextValues) };
  }

  public async set(name: string, values: ProfileValues): Promise<Profile> {
    assertProfileName(name);
    const document = await this.#load();
    if (!document.profiles[name]) {
      throw new Error(`Profile '${name}' does not exist. Create it with 'profile create ${name}'.`);
    }
    const nextValues = {
      ...this.#defaults,
      ...document.profiles[name],
      ...values,
    };
    await this.#validate?.(nextValues);
    document.profiles[name] = nextValues;
    await this.#save(document);
    return { name, values: structuredClone(nextValues) };
  }

  public async setDefault(name: string): Promise<Profile> {
    assertProfileName(name);
    const document = await this.#load();
    const values = document.profiles[name];
    if (!values) {
      throw new Error(`Profile '${name}' does not exist. Create it with 'profile create ${name}'.`);
    }

    document.active = name;
    await this.#save(document);
    return { name, values: structuredClone(values) };
  }

  public async delete(name: string): Promise<{ deleted: string; default: string }> {
    assertProfileName(name);
    const document = await this.#load();
    if (!document.profiles[name]) {
      throw new Error(`Profile '${name}' does not exist.`);
    }
    if (Object.keys(document.profiles).length === 1) {
      throw new Error("Cannot delete the only profile. At least one default profile must exist.");
    }
    if (document.active === name) {
      throw new Error(
        `Cannot delete default profile '${name}'. Set another default with 'profile set-default <name>' first.`,
      );
    }

    delete document.profiles[name];
    if (document.permissions) {
      delete document.permissions[name];
      if (Object.keys(document.permissions).length === 0) {
        delete document.permissions;
      }
    }
    await this.#save(document);
    return { deleted: name, default: document.active };
  }

  public async getPermissions(name?: string): Promise<readonly string[] | undefined> {
    const document = await this.#load();
    const selectedName = name ?? document.active;
    if (!document.profiles[selectedName]) {
      throw new Error(`Profile '${selectedName}' does not exist.`);
    }
    const permissions = document.permissions?.[selectedName];
    return permissions === undefined ? undefined : [...permissions];
  }

  public async setPermissions(
    name: string,
    permissions: readonly string[],
  ): Promise<readonly string[]> {
    assertProfileName(name);
    const document = await this.#load();
    if (!document.profiles[name]) {
      throw new Error(`Profile '${name}' does not exist.`);
    }
    const uniquePermissions = [...new Set(permissions)];
    document.permissions ??= {};
    document.permissions[name] = uniquePermissions;
    await this.#save(document);
    return [...uniquePermissions];
  }

  async #load(): Promise<ProfileDocument> {
    try {
      const contents = await readFile(this.#filePath, "utf8");
      const document = JSON.parse(contents) as Partial<ProfileDocument>;
      if (
        document.version !== 1 ||
        typeof document.active !== "string" ||
        !document.profiles ||
        typeof document.profiles !== "object" ||
        Array.isArray(document.profiles) ||
        Object.keys(document.profiles).length === 0 ||
        !Object.hasOwn(document.profiles, document.active) ||
        Object.values(document.profiles).some(
          (values) => values === null || typeof values !== "object" || Array.isArray(values),
        ) ||
        (document.permissions !== undefined &&
          (document.permissions === null ||
            typeof document.permissions !== "object" ||
            Object.values(document.permissions).some(
              (permissions) =>
                !Array.isArray(permissions) ||
                permissions.some((permission) => typeof permission !== "string"),
            )))
      ) {
        throw new Error(`Unsupported profile document at '${this.#filePath}'.`);
      }

      return document as ProfileDocument;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
        throw error;
      }

      return {
        version: 1,
        active: this.#defaultName,
        profiles: { [this.#defaultName]: structuredClone(this.#defaults) },
      };
    }
  }

  async #save(document: ProfileDocument): Promise<void> {
    await mkdir(dirname(this.#filePath), { recursive: true });
    const temporaryPath = `${this.#filePath}.${process.pid}.tmp`;
    await writeFile(temporaryPath, `${JSON.stringify(document, null, 2)}\n`, {
      encoding: "utf8",
      mode: 0o600,
    });
    await rename(temporaryPath, this.#filePath);
  }
}

import { Entry } from "@napi-rs/keyring";
import type { ScopedSecrets, SecretStore } from "./types.js";

export class KeyringSecretStore implements SecretStore {
  public async get(service: string, account: string): Promise<string | undefined> {
    try {
      return new Entry(service, account).getPassword() ?? undefined;
    } catch (error) {
      throw keyringError("read", error);
    }
  }

  public async set(service: string, account: string, value: string): Promise<void> {
    try {
      new Entry(service, account).setPassword(value);
    } catch (error) {
      throw keyringError("write", error);
    }
  }

  public async delete(service: string, account: string): Promise<void> {
    const entry = new Entry(service, account);
    try {
      if (entry.getPassword() !== null) {
        entry.deletePassword();
      }
    } catch (error) {
      throw keyringError("delete", error);
    }
  }
}

function keyringError(operation: string, error: unknown): Error {
  const message = error instanceof Error ? error.message : String(error);
  return new Error(
    `Could not ${operation} the OS credential store: ${message}. No plaintext fallback is used.`,
    { cause: error },
  );
}

export class MemorySecretStore implements SecretStore {
  readonly #values = new Map<string, string>();

  public async get(service: string, account: string): Promise<string | undefined> {
    return this.#values.get(`${service}\0${account}`);
  }

  public async set(service: string, account: string, value: string): Promise<void> {
    this.#values.set(`${service}\0${account}`, value);
  }

  public async delete(service: string, account: string): Promise<void> {
    this.#values.delete(`${service}\0${account}`);
  }
}

export class ProfileSecrets implements ScopedSecrets {
  readonly #store: SecretStore;
  readonly #service: string;
  readonly #profileName: string;

  public constructor(store: SecretStore, applicationId: string, profileName: string) {
    this.#store = store;
    this.#service = `ai-cli-factory:${applicationId}`;
    this.#profileName = profileName;
  }

  public get(name: string): Promise<string | undefined> {
    return this.#store.get(this.#service, `${this.#profileName}:${name}`);
  }

  public async require(name: string): Promise<string> {
    const value = await this.get(name);
    if (!value) {
      throw new Error(
        `No credential is stored for profile '${this.#profileName}'. Run 'auth login' first.`,
      );
    }
    return value;
  }

  public set(name: string, value: string): Promise<void> {
    return this.#store.set(this.#service, `${this.#profileName}:${name}`, value);
  }

  public delete(name: string): Promise<void> {
    return this.#store.delete(this.#service, `${this.#profileName}:${name}`);
  }
}

import type { Readable, Writable } from "node:stream";
import type { IAppArguments } from "./app-arguments.js";

export type ProfileValues = Record<string, unknown>;

export interface Profile {
  name: string;
  values: ProfileValues;
}

export interface ProfileField {
  name: string;
  flags: string;
  description: string;
  /** A service command cannot run until this field has a non-empty value. */
  required?: boolean;
}

export interface ProfileDefinition {
  defaultName?: string;
  defaults?: ProfileValues;
  fields?: readonly ProfileField[];
  validate?: (values: ProfileValues) => void | Promise<void>;
}

export interface SecretStore {
  get(service: string, account: string): Promise<string | undefined>;
  set(service: string, account: string, value: string): Promise<void>;
  delete(service: string, account: string): Promise<void>;
}

export interface ScopedSecrets {
  get(name: string): Promise<string | undefined>;
  require(name: string): Promise<string>;
  set(name: string, value: string): Promise<void>;
  delete(name: string): Promise<void>;
}

export interface CommandContext {
  appArguments: IAppArguments;
  profile: Profile;
  secrets: ScopedSecrets;
  fetch: typeof globalThis.fetch;
  signal: AbortSignal;
}

export interface CommandInput {
  args: Record<string, unknown>;
  options: Record<string, unknown>;
}

export type CommandHandler = (
  input: CommandInput,
  context: CommandContext,
) => unknown | Promise<unknown>;

export interface OptionDefinition {
  /** Reject a missing value before profile onboarding or handler execution. */
  required?: boolean;
  flags: string;
  description: string;
  defaultValue?: unknown;
  parse?: (value: string, previous: unknown) => unknown;
}

export interface CommandSettings {
  options?: readonly OptionDefinition[];
  permission?: string;
}

export interface CommandDefinition {
  /** Command name followed by optional Commander-style arguments, for example `show <id>`. */
  name: string;
  description: string;
  options?: readonly OptionDefinition[];
  permission?: string;
  children?: readonly CommandDefinition[];
  run?: CommandHandler;
}

export interface PermissionCategory {
  name: string;
  description: string;
  enabledByDefault?: boolean;
}

export interface PermissionGateDefinition {
  categories?: readonly PermissionCategory[];
}

export interface TokenValidationContext {
  appArguments: IAppArguments;
  profile: Profile;
  token: string;
  fetch: typeof globalThis.fetch;
  signal: AbortSignal;
}

export interface TokenAuthDefinition {
  kind: "token";
  secretName: string;
  environmentVariable?: string;
  /** Allows a configured profile (for example guest access) to opt out of token auth. */
  required?: (profile: Profile) => boolean;
  validate?: (context: TokenValidationContext) => unknown | Promise<unknown>;
}

export interface CliRuntime {
  appArguments?: IAppArguments;
  input?: Readable;
  output?: Writable;
  error?: Writable;
  fetch?: typeof globalThis.fetch;
  profileStore?: ProfileStoreContract;
  secretStore?: SecretStore;
}

export interface CliDefinition {
  name: string;
  description: string;
  version?: string;
  applicationId?: string;
  profile?: ProfileDefinition;
  auth?: TokenAuthDefinition;
  permissions?: PermissionGateDefinition;
  commands: readonly CommandDefinition[];
  runtime?: CliRuntime;
}

export interface ProfileStoreContract {
  get(name?: string): Promise<Profile>;
  list(): Promise<{ active: string; profiles: Profile[] }>;
  create(name: string, values?: ProfileValues): Promise<Profile>;
  set(name: string, values: ProfileValues): Promise<Profile>;
  setDefault(name: string): Promise<Profile>;
  delete(name: string): Promise<{ deleted: string; default: string }>;
  getPermissions(name?: string): Promise<readonly string[] | undefined>;
  setPermissions(name: string, permissions: readonly string[]): Promise<readonly string[]>;
}

export interface CliApplication {
  run(argv?: readonly string[]): Promise<number>;
  execute(argv: readonly string[], signal?: AbortSignal): Promise<unknown>;
}

import assert from "node:assert/strict";
import { join } from "node:path";
import test from "node:test";
import {
  AppArguments,
  type AppArgumentsEnvironment,
} from "../src/index.js";

const environment: AppArgumentsEnvironment = {
  AppDomainDirectory: join("root", "app"),
  ApplicationExecutablePath: join("root", "app", "teamcity-cli.js"),
  EnvironmentLocalAppData: join("root", "local"),
  EnvironmentAppData: join("root", "roaming"),
  ProcessId: 42,
};

test("AppArguments preserves the PoeShared current-user profile path contract", () => {
  const arguments_ = new AppArguments({
    AppName: "teamcity-cli",
    Version: "1.2.3",
    Profile: "default",
    Environment: environment,
  });

  assert.equal(arguments_.AppName, "teamcity-cli");
  assert.equal(arguments_.Version, "1.2.3");
  assert.equal(arguments_.Profile, "default");
  assert.equal(arguments_.DataFolder, undefined);
  assert.equal(
    arguments_.LocalAppDataDirectory,
    join("root", "local", "teamcity-cli"),
  );
  assert.equal(
    arguments_.RoamingAppDataDirectory,
    join("root", "roaming", "teamcity-cli"),
  );
  assert.equal(
    arguments_.AppDataDirectory,
    join("root", "roaming", "teamcity-cli", "default"),
  );
  assert.equal(arguments_.TempDirectory, join(arguments_.AppDataDirectory, "temp"));
  assert.equal(arguments_.LogDirectory(), join(arguments_.AppDataDirectory, "log"));
  assert.equal(arguments_.ApplicationExecutableName, "teamcity-cli.js");
  assert.equal(arguments_.ProcessId, 42);
});

test("WithProfile isolates all profile-owned paths without changing application roots", () => {
  const defaultArguments = new AppArguments({
    AppName: "teamcity-cli",
    Profile: "default",
    Environment: environment,
  });
  const productionArguments = defaultArguments.WithProfile("production");

  assert.equal(productionArguments.Profile, "production");
  assert.equal(
    productionArguments.RoamingAppDataDirectory,
    defaultArguments.RoamingAppDataDirectory,
  );
  assert.equal(
    productionArguments.LocalAppDataDirectory,
    defaultArguments.LocalAppDataDirectory,
  );
  assert.equal(
    productionArguments.AppDataDirectory,
    join("root", "roaming", "teamcity-cli", "production"),
  );
  assert.notEqual(
    productionArguments.AppDataDirectory,
    defaultArguments.AppDataDirectory,
  );
});

test("AppArguments rejects names that could escape the application data root", () => {
  assert.throws(
    () =>
      new AppArguments({
        AppName: "teamcity-cli",
        Profile: "../production",
        Environment: environment,
      }),
    /Profile must start/,
  );
});

