      const expected = source === "stdin" ? "synthetic-stdin"
        : source === "environment" ? "synthetic-environment" : "synthetic-stdin";
      assert.equal(await h.cli.run([...command, ...(source === "stdin" ? ["--token-stdin"] : [])]), 0);
